using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra.Lattice.PhysicalLie;

internal sealed class LatticeBRSTPerturbationFiltrationDocument : IScribeDocumentDefinition
{
    private static DocumentBlock Node(string name, string title, string prose, DescribeRole role) => Describe.Lean(
        DescribeId.Create("latticebrstperturbationfiltration-" + name.Replace("_", "-").ToLowerInvariant()),
        DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTPerturbationFiltration." + name), H(title), StatementSource.WithoutFormula(),
        AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))), role);
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Fixed energy and signed filtration for the original lattice BRST charge",
        H("Fixed energy and signed filtration for the original lattice BRST charge"), Blocks(
            Paragraph(Text("The carrier is the actual State D, the all-charge lattice matter carrier tensored with the original countable bc occupation Fock space. D and its rank, null frame F, transverse dimension t and basis B retain their original quantifiers. H has both inverse-Gram hypotheses wherever the source requires them. Charge beta is integral; level and filtration lower are arbitrary integers. Q is the original LatticeBRST.totalCharge D H, and all basis statements use the original actualBasis F B.")),
            Paragraph(Text("This publication proves uniform finite termination of the actual normalized perturbation h(Q-d0) on each literal fixed charge and total-energy sector, with power 2 * level.toNat + 2 for every integer level. The original signed window is -level <= degree <= level + 1, retaining both exceptional ghost occupations {1} and {1,3}. The final finite-HPL wrapper and unused P0 restriction remain complete saved future source; no compilation of that residual is claimed. This is an algebraic termination result and does not assert a physical no-ghost theorem.")),
            Node("groundEnergy", "Charge ground energy", "For every lattice D and integral charge beta, groundEnergy beta is bilinear D beta beta, cast to C, divided by 2.", DescribeRole.Definition),
            Node("totalL0", "Actual total zero mode", "For every D and matrix H of size Fin D.rank, totalL0 H is the original matter mode at 0 plus the original ghost Virasoro mode at 0, on the full State D.", DescribeRole.Definition),
            Node("oscillatorLevel", "Oscillator frequency level", "For every transverse dimension t and exponent vector m, oscillatorLevel m is Finsupp.weight frequencyWeight m.", DescribeRole.Definition),
            Node("indexLevel", "Integer level of every raw occupation", "For every StateIndex D t, indexLevel is oscillatorLevel plus BcGhostRelativeEnergy.relativeEnergy of the raw ghost occupation. No occupation is discarded.", DescribeRole.Definition),
            Node("totalL0_basis", "Energy of the actual basis", "For every D, null frame F, transverse basis B, H satisfying both H * gramComplex D = 1 and gramComplex D * H = 1, and every i, totalL0 H applied to actualBasis F B i equals (groundEnergy i.1.1 + (indexLevel i : C) - 1) times that same basis vector.", DescribeRole.Theorem),
            Node("totalL0_diagonal", "Diagonal form on the actual basis", "For the same arbitrary D, F, B and H with both inverse-Gram identities, totalL0 H is diagonal on actualBasis F B with eigenvalue groundEnergy i.1.1 + (indexLevel i : C) - 1.", DescribeRole.Theorem),
            Node("fixedSector", "Literal fixed charge and total energy", "For every D, H, integral charge beta and integer level, fixedSector H beta level is the submodule of the full State D defined by chargeProject beta v = v and totalL0 H v = (groundEnergy beta + (level : C) - 1) times v. There is no global energy cutoff.", DescribeRole.Definition),
            Node("mem_fixedSector_iff", "Exact coefficient characterization of the sector", "For arbitrary F and B and both inverse-Gram identities for H, v belongs to fixedSector H beta level if and only if every nonzero actualBasis coefficient has charge beta and indexLevel equal to level. All integer levels remain quantified.", DescribeRole.Theorem),
            Node("signedFiltration", "Original signed filtration", "For arbitrary beta and integers level and lower, signedFiltration F B beta level lower is the C-span of the actual basis vectors with charge beta, indexLevel equal to level and lower <= degree. It is a submodule of the original State D.", DescribeRole.Definition),
            Node("degree_bounds", "Full signed degree window", "For every original StateIndex D t, -indexLevel i <= degree i and degree i <= indexLevel i + 1. The proof uses the frequency-weight exponent bound and the ghost charge/energy split, including sites 1 and 3.", DescribeRole.Theorem),
            Node("basis_mem_fixedSector", "Every original ket lies in its literal sector", "For arbitrary D, F, t, B and H with both inverse-Gram identities, every actualBasis F B i belongs to fixedSector H i.1.1 (indexLevel i). This is used in the actual normalized perturbation basis step.", DescribeRole.Theorem),
            Node("mem_signedFiltration_iff", "Signed filtration in actual coordinates", "For arbitrary beta, integer level and integer lower, v belongs to signedFiltration F B beta level lower exactly when every nonzero actualBasis coefficient has charge beta, indexLevel equal to level, and degree at least lower.", DescribeRole.Theorem),
            Node("sector_mem_filtration", "Initial lower degree bound", "For both inverse-Gram identities and every integer level, each vector in fixedSector H beta level belongs to signedFiltration F B beta level (-level). This is the base of the termination iteration.", DescribeRole.Theorem),
            Node("filtration_exhausted", "Upper endpoint exhausts the filtration", "For any integer level and lower with level + 1 < lower, signedFiltration F B beta level lower is the zero submodule. The upper signed degree bound proves this on the span generators.", DescribeRole.Theorem),
            Node("totalL0_Q", "Original Q preserves total energy in every rank", "For arbitrary rank and both inverse-Gram identities, totalL0 H commutes with the original LatticeBRST.totalCharge D H. This uses the existing zero-mode covariance, whose anomaly is zero at mode zero.", DescribeRole.Theorem),
            Node("Q_preserves", "Original Q preserves the literal sector", "For arbitrary integral beta, integer level and v in the literal fixedSector, the original Q v lies in the same sector. The charge and energy conditions are both preserved.", DescribeRole.Theorem),
            Node("totalL0_d0", "Leading differential preserves total energy", "Under both inverse-Gram identities, totalL0 H commutes with the actual d0 F beta, using the locally finite quartet family and the original matter/ghost Ward identities.", DescribeRole.Theorem),
            Node("totalL0_h", "Actual quartet homotopy preserves total energy", "Under both inverse-Gram identities, totalL0 H commutes with h F B beta = R F beta * invM F B. Both actual original factors are used.", DescribeRole.Theorem),
            Node("d0_preserves", "Leading differential preserves the literal sector", "For the original D, F, B and both inverse-Gram identities, d0 F beta maps fixedSector H beta level into itself for every integer level.", DescribeRole.Theorem),
            Node("h_preserves", "Actual homotopy preserves the literal sector", "For the same arbitrary original parameters and every integer level, h F B beta maps fixedSector H beta level into itself. This is consumed by the actual normalized perturbation step.", DescribeRole.Theorem),
            Node("normalizedPerturbation", "Actual normalized original-Q perturbation", "In the original LatticeBRSTFiniteTransfer namespace, normalizedPerturbation F B H beta is exactly h F B beta * (LatticeBRST.totalCharge D H - d0 F beta), acting on the full original State D.", DescribeRole.Definition),
            Node("actual_normalized_perturbation_termination", "Uniform original-Q finite termination", "For arbitrary original D, null frame F, transverse t and B, H satisfying both inverse-Gram identities, integral beta, every integer level and v with chargeProject beta v = v and totalL0 H v = (groundEnergy beta + (level : C) - 1) times v, the 2 * level.toNat + 2 power of h F B beta * (LatticeBRST.totalCharge D H - d0 F beta) kills v. No rank-26 hypothesis, nonzero-charge condition, relative-kernel condition or energy cutoff is added. The proof constructs the all-k invariant A^k v in signedFiltration at -level + k from the actual raising and energy-preservation chain, then uses exhaustion; negative levels are included by the same arithmetic. The public qualified name remains in LatticeBRSTFiniteTransfer.", DescribeRole.Theorem),
            Paragraph(Text("The coefficient, signed-window and operator-preservation statements are consumed proof helpers. The substantive candidate is the uniform iteration invariant and termination on all literal fixed-energy sectors; the frozen full-original raising result supplies one step and the existing relative-shell theorem does not cover this carrier sector. This proof-shape assessment requires exact-head semantic review and is not established by kernel or Frozen checks. Escape audits remain unfinished in issue 30101 except to the extent current binding evidence validates the retained degree_bounds registration.")))));
}
